import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"为业务接口建立确定性性能预算","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/perf-gates","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/perf-gates.md","filePath":"tutorials/perf-gates.md"}'),r={name:"tutorials/perf-gates.md"};function p(n,a,o,d,l,h){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="为业务接口建立确定性性能预算" tabindex="-1">为业务接口建立确定性性能预算 <a class="header-anchor" href="#为业务接口建立确定性性能预算" aria-label="Permalink to &quot;为业务接口建立确定性性能预算&quot;">​</a></h1><p>把性能合同写成可自动检查的行数、数据库往返次数和载荷字节数。这样业务演进时，额外副作用、N+1 与列表携带大正文会成为明确的失败；跨机器的 P95/P99 另写<a href="./load-reports">负载报告</a>。</p><p>本指南需要已通过 HTTP 行为测试的业务、真实 PostgreSQL，以及已安装依赖的工作副本。命令在仓库根目录执行，测试使用隔离数据库。</p><h2 id="从真实-http-操作定义预算" tabindex="-1">从真实 HTTP 操作定义预算 <a class="header-anchor" href="#从真实-http-操作定义预算" aria-label="Permalink to &quot;从真实 HTTP 操作定义预算&quot;">​</a></h2><p>现有两份实现可直接运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf_registration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf_documents</span></span></code></pre></div><table tabindex="0"><thead><tr><th>公开操作</th><th>当前断言</th><th>代码位置</th></tr></thead><tbody><tr><td>注册成功</td><td>1 User、1 Credential、1 有效 Membership、1 注册 Audit；Session 单独计数；无 Job/Notification</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/api/tests/perf_registration.rs" target="_blank" rel="noreferrer">perf_registration.rs</a></td></tr><tr><td>重复注册</td><td>409，用户与审计没有重复写入</td><td>同上</td></tr><tr><td>文档列表</td><td>数据规模增加时最多 4 次数据库往返；载荷最多 256 KiB，不含正文</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/api/tests/perf_documents.rs" target="_blank" rel="noreferrer">perf_documents.rs</a></td></tr><tr><td>创建或导出</td><td>业务行、Audit、Job、通知意图按操作精确计数；重放不新增副作用</td><td>同上</td></tr></tbody></table><p>给自己的模块新增 <code>apps/api/tests/perf_&lt;业务&gt;.rs</code>，沿用真实 Router 和 <code>#[sqlx::test(migrations = &quot;../../migrations&quot;)]</code>。先完成一次 HTTP 操作，再比较该操作前后的行数；拒绝和幂等重放也要检查零额外写入。为列表播种小、大两档数据，比较数据库往返和响应字节，避免只在空库里检查。</p><p>这里的表计数属于专门的性能观察入口，普通业务测试仍从公开 HTTP 结果验收。跨模块 Audit/Job 的计数是副作用合同，不能让业务实现直接读写它们的私有表。</p><h2 id="计量查询次数" tabindex="-1">计量查询次数 <a class="header-anchor" href="#计量查询次数" aria-label="Permalink to &quot;计量查询次数&quot;">​</a></h2><p>文档预算使用 sqlx 的 <code>sqlx::query</code> tracing 事件计量真实执行语句，完整订阅器在 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/api/tests/perf_documents.rs" target="_blank" rel="noreferrer">perf_documents.rs</a>。订阅器处理 callsite interest 缓存并按测试线程计数；复用它的做法时保留隔离条件，不能把并发测试的全部查询累加到同一请求。</p><p>如果新业务把查询移到额外的异步任务，先确认计量范围确实包含该执行路径。通过几次计数不代表动态 SQL 或不同运行配置已经覆盖。</p><h2 id="客户端包体预算" tabindex="-1">客户端包体预算 <a class="header-anchor" href="#客户端包体预算" aria-label="Permalink to &quot;客户端包体预算&quot;">​</a></h2><p>后端项目只有新增 Web 客户端时才需要这一项：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/perf-bundle.mjs</span></span></code></pre></div><p>工具真实构建 Web 并按 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/scripts/perf/baselines.json" target="_blank" rel="noreferrer">baselines.json</a> 检查 gzip 字节。当前初始集上限 400 KiB、异步 chunk 上限 500 KiB；Markdown、设计系统、图标目录必须懒加载。初始集同时包含入口 script 和 modulepreload，静态依赖不能借异步预算绕过检查。报告写到 <code>.scratch/perf/bundle-report.json</code>。</p><h2 id="查询计划是诊断材料" tabindex="-1">查询计划是诊断材料 <a class="header-anchor" href="#查询计划是诊断材料" aria-label="Permalink to &quot;查询计划是诊断材料&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/perf-query-plans.mjs</span></span></code></pre></div><p>工具在一次性数据库的 10 / 1,000 / 100,000 行档位执行参考业务的 <code>EXPLAIN ANALYZE</code>，输出 <code>.scratch/perf/query-plans.json</code>。为自己的热查询增加等价的播种与查询，保持 SQL 与实现同步。报告记录计划和时长，不把 Seq Scan 或某个毫秒数直接判失败；内联字面量的计划也可能不同于 sqlx 预编译语句路径。</p><h2 id="接入日常检查与调整基线" tabindex="-1">接入日常检查与调整基线 <a class="header-anchor" href="#接入日常检查与调整基线" aria-label="Permalink to &quot;接入日常检查与调整基线&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-ci</span></span></code></pre></div><p><code>just perf</code> 运行现有预算测试、包体门禁和查询计划报告；新测试名应同步加入其定向配方。后端完整套件会自动执行新增集成测试。<code>just check</code> 通过 <code>just test</code> 和 <code>perf-ci</code> 覆盖确定性预算，不隐式执行负载或桌面长测。</p><p>失败时先检查新增写入、N+1、列表投影和同步导入。合理的预算变更应在同一 PR 提供变更前后完整测量、理由和旧/新阈值，并更新基线；不要在引入回归的提交中静默抬高上限。</p><p>注册预算、包体计量与报告工具属于 Core。文档预算随知识库示例移除；查询计划工具在缺少示例时说明并退出。为自己的业务登记测试所有权和自己的预算，参考应用的通过结果不能替代它。</p><p>下一步：<a href="./load-reports">为自己的热路径编写受控负载场景</a>。</p><hr><p>源码版本：<code>88c22a67f072</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/docs/tutorials/24-perf-gates.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,27)])])}const u=e(r,[["render",p]]);export{b as __pageData,u as default};
